function appointmentCard(a,hero=false){const d=appointmentDoctor(a),f=facilityFor(a),active=['pending','confirmed'].includes(a.status);return '<article class="connected-appointment '+(hero?'connected-next-appointment':'')+'"><div class="appointment-date-block"><span>'+E(new Date(String(a.requested_date).slice(0,10)+'T12:00:00').toLocaleDateString('en',{month:'short'}))+'</span><strong>'+E(String(a.requested_date).slice(8,10))+'</strong><small>'+E(times(a.requested_time))+'</small></div><div class="appointment-facts">'+(hero?'<span class="connected-eyebrow">YOUR NEXT VISIT · '+E(countdown(a.requested_date))+'</span>':'')+'<h3>'+E(a.reason||types[a.visit_type]||'Care visit')+'</h3><p>'+E(a.doctor_name||d?.full_name||'Doctor to confirm')+'<br>'+E(a.hospital_name||f?.name||'Centre to confirm')+(a.unit_label||d?.unit_label?' · Unit '+E(a.unit_label||d.unit_label):'')+'</p><small>Room: '+E(a.room||d?.room||'Confirm with the clinic')+' · Token: not assigned here</small><span class="connected-status">'+E(a.status==='pending'?'Request sent · awaiting confirmation':a.status)+'</span></div><div class="appointment-card-actions">'+(f?'<a class="btn btn--primary" target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(f.lat+','+f.lng)+'">Get directions ↗</a>':'<button type="button" class="btn btn--primary" data-route="facilities">Find the centre →</button>')+'<button type="button" class="link-btn" data-connected-calendar="'+E(a.id)+'">Add to calendar</button></div><details class="appointment-expanded"><summary>Prepare for this visit</summary><p>Bring your care card and relevant previous reports. Confirm fasting or other preparation with the clinician; this app does not set fasting instructions.</p><p>Live queue position, floor and token allocation are not connected here. A pending request is not a confirmed clinic slot.</p>'+(a.child_id?'<p>For '+E(state.children?.find(c=>c.id===a.child_id)?.name||'the selected baby')+' only. Records remain separate.</p>':'')+(a.doctor_notes?'<blockquote><strong>Recorded by your doctor</strong><p>'+E(a.doctor_notes)+'</p></blockquote>':'')+'<div class="connected-links"><button type="button" class="link-btn" data-connected-questions="'+E(a.reason||'my visit')+'">Prepare questions →</button><button type="button" class="link-btn" data-connected-share-visit="'+E(a.id)+'">Share visit details →</button>'+(active?'<button type="button" class="link-btn" data-connected-reschedule="'+E(a.id)+'">Reschedule</button><button type="button" class="link-btn" data-connected-cancel="'+E(a.id)+'">Cancel request</button>':'<button type="button" class="link-btn" data-connected-rebook="'+E(a.id)+'">Request another visit →</button>')+'</div></details></article>';}
function calendar(){const d=new Date(),base=new Date(d.getFullYear(),d.getMonth()+month,1),year=base.getFullYear(),m=base.getMonth(),n=new Date(year,m+1,0).getDate(),offset=(base.getDay()+6)%7;let html='<aside class="connected-calendar"><header><button type="button" data-connected-month="-1" aria-label="Previous month">‹</button><strong>'+E(base.toLocaleDateString(document.documentElement.lang||'en',{month:'long',year:'numeric'}))+'</strong><button type="button" data-connected-month="1" aria-label="Next month">›</button></header><div>'+['M','T','W','T','F','S','S'].map(x=>'<small>'+x+'</small>').join('')+'<span></span>'.repeat(offset);for(let i=1;i<=n;i++){const date=year+'-'+String(m+1).padStart(2,'0')+'-'+String(i).padStart(2,'0'),visits=(state.appointments||[]).filter(a=>String(a.requested_date).startsWith(date)&&a.status!=='cancelled');html+='<span class="'+(date===M().today()?'calendar-today ':'')+(visits.length?'calendar-visit':'')+'" title="'+E(visits.length?visits.length+' visit request(s)':'No visit recorded')+'">'+i+'</span>';}return html+'</div><p>● Visit requested or recorded<br>Check each visit’s confirmation status.</p></aside>';}
function renderAppointments(){const root=$('connectedAppointments');if(!root)return;const all=state.appointments||[],upcoming=all.filter(a=>M().upcoming(a)).sort((a,b)=>String(a.requested_date).localeCompare(String(b.requested_date))||times(a.requested_time).localeCompare(times(b.requested_time))),next=upcoming[0];const rows=tab==='upcoming'?upcoming:tab==='cancelled'?all.filter(a=>a.status==='cancelled'):all.filter(a=>a.status!=='cancelled'&&!M().upcoming(a));root.innerHTML='<header class="connected-heading"><div><span class="connected-eyebrow">YOUR CARE, ON THE CALENDAR</span><h1>A little time for you.</h1><p>Plan a visit, prepare your questions, keep care moving.</p></div><button type="button" class="btn btn--primary" data-connected-book>＋ Book a new appointment</button></header>'+(state.offline?'<p class="connected-notice">Connect to load appointments and current clinic windows. Your saved care timeline is still available.</p>':'')+'<div class="connected-visit-overview"><div>'+(next?appointmentCard(next,true):'<div class="connected-empty">'+(window.PatientVisuals?.emptyArt('care')||'<span>♡</span>')+'<h2>Your next visit starts here.</h2><p>No upcoming appointment is recorded. Choose a clinic and request a visit when you need one.</p><button type="button" class="link-btn" data-connected-book>Find a clinic window →</button></div>')+'</div>'+calendar()+'</div><div class="connected-tabbar" role="group" aria-label="Appointment history">'+[['upcoming','Upcoming'],['past','Past'],['cancelled','Cancelled']].map(([k,t])=>'<button type="button" data-connected-tab="'+k+'" aria-pressed="'+(k===tab)+'">'+t+'</button>').join('')+'</div><div class="connected-appointment-list">'+rows.filter(a=>tab!=='upcoming'||a.id!==next?.id).map(a=>appointmentCard(a)).join('')+(!rows.length?'<p class="connected-notice">No '+tab+' appointments recorded.</p>':tab==='upcoming'&&rows.length===1?'<p class="connected-notice">Your upcoming visit is shown above.</p>':'')+'</div><details class="connected-demo"><summary>What is connected in this demo?</summary><p>Requests use hospital unit OPD days and appear on the doctor’s appointment list. Local hospital staff can see mirrored requests for their permitted cohort.</p><p>Teleconsultation, live tokens, SMS/WhatsApp and caregiver reminders are not connected. External messaging requires a provider integration.</p></details>';}
async function refresh(){await Promise.all([window.PatientExperience?.refreshAppointments?.(),window.PatientExperience?.refreshTimeline?.()]);}
