 const form=d.querySelector('form'),q=n=>form.elements.namedItem(n),daysEl=d.querySelector('.booking-days'),timesEl=d.querySelector('.booking-times'),review=d.querySelector('.booking-review'),submit=form.querySelector('[type=submit]');let date='',requestedTime='',days=[],version=0,confirmed=false;
 q('visit_type').value=old?.visit_type||(old?.child_id?'paediatric':/test|ogtt|blood/i.test(prefill)?'test':/scan/i.test(prefill)?'scan':state.post?.active?'postpartum':'antenatal');q('subject').value=old?.child_id||'';q('notes').value=old?'':prefill;if(old){q('visit_type').disabled=true;q('subject').disabled=true;q('facility').disabled=true;}
 const defaultDoctor=catalog.doctors.find(x=>String(x.id)===String(old?.doctor_id))||catalog.doctors.find(x=>x.assigned);if(defaultDoctor)q('facility').value=defaultDoctor.facility_id;
 function setReview(){confirmed=false;const doctor=catalog.doctors.find(x=>String(x.id)===q('doctor').value);review.textContent=date&&requestedTime?fmt(date)+' · '+requestedTime+' · '+(doctor?.full_name||'')+' · '+(doctor?.unit_label?'Unit '+doctor.unit_label:'Unit to confirm'):'Choose a day and time to review your request.';submit.disabled=!date||!requestedTime;submit.textContent='Review request →';}
