 function doctors(){const facility=catalog.facilities.find(x=>x.id===q('facility').value);d.querySelector('.booking-facility-info').textContent=facility?[facility.address,facility.fee_status,'Distance is not recorded. See Nearby care for location-based options.'].join(' · '):'Facility details unavailable.';let available=catalog.doctors.filter(x=>x.facility_id===q('facility').value);if(['baby_vaccine','paediatric'].includes(q('visit_type').value))available=available.filter(x=>/paediatr|neonat/i.test(x.specialization));q('doctor').innerHTML=available.map(x=>'<option value="'+x.id+'">'+E(x.full_name)+(x.assigned?' · Your assigned doctor':'')+'</option>').join('');if(defaultDoctor&&available.some(x=>x.id===defaultDoctor.id))q('doctor').value=defaultDoctor.id;slots();}
