 daysEl.onclick=e=>{const b=e.target.closest('[data-book-day]');if(!b)return;date=b.dataset.bookDay;requestedTime='';daysEl.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderTimes();};timesEl.onclick=e=>{const b=e.target.closest('[data-book-time]');if(!b)return;requestedTime=b.dataset.bookTime;renderTimes();};q('notes').oninput=()=>{confirmed=false;submit.textContent='Review request →';};
